import{_ as a,a0 as i,w as l,s as n,I as e,x as s,a1 as r,A as p,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"用 Recast.AI 創建一個聊天機器人 | LCTT x X-CMD","titleTemplate":false,"description":"用 Recast.AI 創建一個聊天機器人 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Recast.AI 創建一個聊天機器人 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Recast.AI 創建一個聊天機器人 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20191118 Creating a Chat Bot with Recast.AI","title":"用 Recast.AI 創建一個聊天機器人","tag":"202012","desc":""},"relativePath":"202012/20191118 Creating a Chat Bot with Recast.AI.md","filePath":"[post].md"}'),g={name:"202012/20191118 Creating a Chat Bot with Recast.AI.md"};function m(d,t,c,f,b,h){const o=i("Link");return l(),n("div",null,[t[23]||(t[23]=e("h1",{id:"用-recast-ai-創建一個聊天機器人",tabindex:"-1"},[s("用 Recast.AI 創建一個聊天機器人 "),e("a",{class:"header-anchor",href:"#用-recast-ai-創建一個聊天機器人","aria-label":"Permalink to “用 Recast.AI 創建一個聊天機器人”"},"​")],-1)),e("p",null,[r(o,{href:"https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/04/Build-ChatBoat.jpg?fit=900%2C572&ssl=1"},{default:p(()=>[...t[0]||(t[0]=[e("img",{src:"https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/04/Build-ChatBoat.jpg?resize=696%2C442&ssl=1",alt:"",title:"Build ChatBoat"},null,-1)])]),_:1})]),t[24]||(t[24]=e("blockquote",null,[e("p",null,"據 Gartner 2018 年 2 月的報告，“到 2020 年，25% 的客户服務和支持業務將在參與渠道中整合虛擬客户助理（VCA）或聊天機器人技術，而 2017 年只有不到 2%。”鑑於此，讀者會發現本教程對理解開源的 Recast.AI 機器人創建平台的工作原理很有幫助。")],-1)),t[25]||(t[25]=e("p",null,"聊天機器人，包括基於語音的以及其他技術的，已經實際使用了有一陣子了。從讓用户參與謀殺解密遊戲，到幫助完成房地產交易和醫療診斷，聊天機器人已經跨越了多個領域。",-1)),t[26]||(t[26]=e("p",null,"有許多平台可以讓用户創建和部署機器人。Recast.AI（在被 SAP 收購之後現在是 SAP Conversational AI）是其中的先行者。",-1)),t[27]||(t[27]=e("p",null,"酷炫的界面、協作性以及它所提供的分析工具，讓它成為流行的選擇。",-1)),t[28]||(t[28]=e("p",null,"正如 Recast 官方網站説的，“它是一個創建、訓練、部署和監控智能機器人的終極協作平台。”",-1)),t[29]||(t[29]=e("h3",{id:"創建一個基礎的機器人",tabindex:"-1"},[s("創建一個基礎的機器人 "),e("a",{class:"header-anchor",href:"#創建一個基礎的機器人","aria-label":"Permalink to “創建一個基礎的機器人”"},"​")],-1)),t[30]||(t[30]=e("p",null,"讓我們來看看如何在 Recast 創建一個基礎的機器人。",-1)),e("ol",null,[e("li",null,[t[2]||(t[2]=s("在 ",-1)),r(o,{href:"https://cai.tools.sap"},{default:p(()=>[...t[1]||(t[1]=[s("https://cai.tools.sap",-1)])]),_:1}),t[3]||(t[3]=s(" 創建一個賬户。註冊可以使用電子郵箱或者 Github 賬户。",-1))]),t[4]||(t[4]=e("li",null,"在你登錄之後，你會進入儀表板。點擊右上角 “+” 新建機器人圖標新建一個機器人。",-1)),t[5]||(t[5]=e("li",null,[s("在下一個界面，你會看到一系列可選的預定義技能。暫時選擇"),e("ruby",null,[s("問候"),e("rt",null,"Greetings")]),s("”（圖 1）。這個機器人已經經過訓練，能夠理解基本的問候。 "),e("img",{src:"https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-1-Setting-the-bot-properties.jpg",alt:"圖 1: 設置機器人屬性"})],-1)),t[6]||(t[6]=e("li",null,"給機器人提供一個名字。目前來説，你可以讓機器人講一些笑話，所以我們將它命名為 Joke Bot，選擇英語作為默認語言。",-1)),t[7]||(t[7]=e("li",null,"因為你不會處理任何敏感信息，所以在數據策略下選擇非個人數據。然後選擇公共機器人選項並點擊創建一個機器人。",-1))]),t[31]||(t[31]=u(`<p>所以這就是你在 Recast 平台創建的機器人。</p><h3 id="開發一個機器人的五個階段" tabindex="-1">開發一個機器人的五個階段 <a class="header-anchor" href="#開發一個機器人的五個階段" aria-label="Permalink to “開發一個機器人的五個階段”">​</a></h3><p>用 Recast 官方Blog的話説，在機器人的生命中有五個階段。</p><ul><li>訓練——教授機器人需要理解的內容</li><li>構建——使用機器人構建工具創建你的對話流</li><li>編寫代碼——將機器人連接到外部 API 或資料庫</li><li>連接——將機器人發佈到一個或多個消息平台</li><li>監控——訓練機器人讓它更敏鋭，並且瞭解其使用情況</li></ul><h3 id="通過意圖訓練機器人" tabindex="-1">通過意圖訓練機器人 <a class="header-anchor" href="#通過意圖訓練機器人" aria-label="Permalink to “通過意圖訓練機器人”">​</a></h3><p>你可以在儀表板上看到搜索、分叉或創建一個<ruby>意圖<rt>intent</rt></ruby>的選項。“‘意圖’是一系列含義相同但構造不同的表達。‘意圖’是你的機器人理解能力的核心。每個‘意圖’代表了機器人可以理解的一種想法。”（摘自 Recast.AI 網站）</p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-2-Setting-the-bot-properties.jpg" alt="圖 2: 機器人面板"></p><p>就像先前定的，你需要一個講笑話的機器人。所以底線是這個機器人可以理解用户在要求它講笑話，它不應該在用户僅僅説了“Hi”的情況下回復一個笑話——這可不妙。把用户可能説的話進行分組，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tell me a joke.（給我講個笑話。）</span></span>
<span class="line"><span>Tell me a funny fact.（告訴我一個有趣的事實。）</span></span>
<span class="line"><span>Can you crack a joke?（你可以講個笑話嗎？）</span></span>
<span class="line"><span>What’s funny today?（今天有什麼有趣的？）</span></span></code></pre></div><p>……</p><p>在繼續從頭開始創建意圖之前，讓我們來看看搜索/分叉選項。在搜索框輸入 “Joke”（圖 3）。系統給出了全球的 Recast 用户創建的公開的意圖清單，這就是為什麼説 Recast 天然就是協作性質的。所以其實沒有必要從頭開始創建所有的意圖，可以在已經創建的基礎上進行構建。這就降低了訓練具有常見意圖的機器人所需的投入。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-3-Searching-an-intent.jpg" alt="圖 3: 搜索一個意圖"></p><ul><li>選擇列表中的第一個意圖並將其分叉到機器人上。</li><li>點擊<ruby>分叉<rt>Fork</rt></ruby>按鈕。這個意圖就添加到了機器人中（圖 4）。 <img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-4-@joke-intent.jpg" alt="圖 4: @joke 意圖"></li><li>點擊意圖 @joke，會顯示出這個意圖中已經存在的<ruby>表達<rt>expression</rt></ruby>列表（圖 5）。 <img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-5-Predefined-expressions.jpg" alt="圖 5: 預定義表達"></li><li>向其添加更多的表達（圖 6）。 <img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-6-Suggested-expressions.jpg" alt="圖 6: 建議的表達"></li></ul><p>添加了一些表達之後，機器人會給出一些建議，像圖 7 展示的那樣。選擇幾個將它們添加到意圖中。你還可以根據機器人的上下文，標記你自己的自定義實體來檢測關鍵詞。</p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-7-Suggested-expressions.jpg" alt="圖 7: 建議的表達"></p><h3 id="技能" tabindex="-1">技能 <a class="header-anchor" href="#技能" aria-label="Permalink to “技能”">​</a></h3><p><ruby>技能<rt>skill</rt></ruby>是一塊有明確目的的對話，機器人可以據此運行並達到目標。它可以像打招呼那麼簡單，也可以更復雜，比如基於用户提供的信息提供電影建議。</p><p>技能需要的不能只是一對問答，它需要多次交互。比如考慮一個幫你學習匯率的機器人。它一開始會問原貨幣，然後是目標貨幣，最後給出準確回應。結合技能可以創建複雜的對話流。</p><p>下面是如何給笑話機器人創建技能：</p><ul><li>去到 構建（Build） 頁。點擊 “+” 圖標創建技能。</li><li>給技能命名 “Joke”（圖 8） <img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-8-Skills-dashboard.jpg" alt="圖 8: 技能面板"></li><li>創建之後，點擊這個技能。你會看到四個標籤。<ruby>讀我<rt>Read me</rt></ruby>、<ruby>觸發器<rt>Triggers</rt></ruby>、<ruby>需求<rt>Requirements</rt></ruby>和 <ruby>動作<rt>Actions</rt></ruby>。</li><li>切換到需求頁面。只有在笑話意圖存在的時候，你才應該存儲信息。所以，像圖 9 那樣添加一個需求。 <img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-9-Adding-a-trigger.jpg" alt="圖 9: 添加一個觸發器"></li></ul><p>由於這個簡單的使用範例，你不需要在需求選項卡中考慮任何特定的需求，但可以考慮只有當某些關鍵字或實體出現時才需要觸發響應的情況——在這種情況下你需要需求。</p><p>需求是某個技能執行動作之前需要檢索的意圖或實體。需求是對話中機器人可以使用的重要信息。例如用户的姓名或位置。一旦一個需求完成，相關的值就會存儲在機器人的內存中，供整個對話使用。</p><p>現在讓我們轉到動作頁面設置<ruby>回應<rt>response</rt></ruby>（參見圖 10）。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-10-Adding-actions.jpg" alt="圖 10: 添加動作"></p><p>點擊添加<ruby>新消息組<rt>new message group</rt></ruby>。然後選擇<ruby>發送消息<rt>Send message</rt></ruby>並添加一條文本消息，在這個例子中可以是任何笑話。當然，你肯定不想讓你的機器人每次都説一樣的笑話，你可以添加多條消息，每次從中隨機選擇一條。</p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-11-Adding-text-messages.jpg" alt="圖 11: 添加文本消息"></p><h3 id="頻道集成" tabindex="-1">頻道集成 <a class="header-anchor" href="#頻道集成" aria-label="Permalink to “頻道集成”">​</a></h3><p>一個成功的機器人還依賴於它的易得性。Recast 有不少的內置消息頻道集成，如 Skype for Business、Kik Messenger、Telegram、Line、Facebook Messenger、Slack、Alexa 等等。除此之外，Recast 還提供了 SDK 用於開發自定義的頻道。</p><p>此外，Recast 還提供一個可立即使用的網頁聊天（在連接頁面中）。你可以自定義顏色主題、標題、機器人頭像等。它給你提供了一個可以添加到頁面的腳本標籤。你的界面現在就可以使用了（圖 12）。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-12-Setting-up-webchat.jpg" alt="圖 12: 設置網絡聊天"></p><p>網頁聊天的代碼是開源的，開發者可以更方便地定製外觀、標準回應類型等等。面板提供瞭如何將機器人部署到各種頻道的逐步過程説明。這個笑話機器人部署在 Telegram 和網頁聊天上，就像圖 13 展示的那樣。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-13-Webchat-deployed.jpg" alt="圖 13: 網頁聊天部署"></p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-14-Bot-deployed-in-Telegram.jpg" alt="圖 14: Telegram 中開發的機器人"></p><h3 id="還有更多" tabindex="-1">還有更多 <a class="header-anchor" href="#還有更多" aria-label="Permalink to “還有更多”">​</a></h3><p>Recast 支持多語言，創建機器人的時候選擇一個語言作為基礎，但之後你有選項可以添加更多你想要的語言。</p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/11/Figure-15-Multi-language-bot.jpg" alt="圖 15: 多語言機器人"></p><p>這裏的例子是一個簡單的靜態笑話機器人，實際使用中可能需要更多的和不同系統的交互。Recast 有 Web 鈎子功能，用户可以連接到不同的系統來獲取回應。同時它還有詳細的 API 文檔來幫助使用平台的每個獨立功能。</p><p>至於分析，Recast 有一個監控面板，幫助你瞭解機器人的準確度以及更加深入地訓練機器人。</p><hr>`,39)),e("p",null,[t[9]||(t[9]=s("via: ",-1)),r(o,{href:"https://opensourceforu.com/2019/11/creating-a-chat-bot-with-recast-ai/"},{default:p(()=>[...t[8]||(t[8]=[s("https://opensourceforu.com/2019/11/creating-a-chat-bot-with-recast-ai/",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=s("作者：",-1)),r(o,{href:"https://opensourceforu.com/author/athira-lekshmi/"},{default:p(()=>[...t[10]||(t[10]=[s("Athira Lekshmi C.V",-1)])]),_:1}),t[15]||(t[15]=s(" 選題：",-1)),r(o,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[11]||(t[11]=[s("lujun9972",-1)])]),_:1}),t[16]||(t[16]=s(" 譯者：",-1)),r(o,{href:"https://github.com/alim0x"},{default:p(()=>[...t[12]||(t[12]=[s("alim0x",-1)])]),_:1}),t[17]||(t[17]=s(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[13]||(t[13]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=s("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[18]||(t[18]=[s("LCTT",-1)])]),_:1}),t[21]||(t[21]=s(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:p(()=>[...t[19]||(t[19]=[s("Linux中國",-1)])]),_:1}),t[22]||(t[22]=s(" 榮譽推出",-1))])])}const C=a(g,[["render",m]]);export{y as __pageData,C as default};
